#
# Apply the rock5 changes to a Mesa Android.bp freshly generated by
# ninja-to-soong (desktop/mesa3d/panvk), so it builds on Android 15:
#
#  1. src/vulkan/runtime/astc_spv.h is generated here with the host
#     glslangValidator and checked in; Android 15 has no glslangValidator
#     module, so the genrule becomes a copy.
#  2. Mesa's IMapper gralloc backend (u_gralloc_imapper5_api.cpp) is added and
#     vulkan.panfrost links libui. Meson only builds it when it finds libui,
#     which the android-stub configuration lacks; without it Mesa uses the
#     fallback gralloc (DRM_FORMAT_MOD_INVALID for every buffer) and PanVK
#     crashes importing SurfaceFlinger's buffers.
#
#   tools/mesa/fixup-android-bp.py <mesa checkout>

import os
import re
import subprocess
import sys

DRIVER = "desktop-mesa3d_panvk_libvulkan_panfrost"
UGRALLOC = "desktop_mesa3d_panvk_src_util_u_gralloc_lib_mesa_u_gralloc_a"
IMAPPER = "rock5_mesa_u_gralloc_imapper5"
ASTC_SRC = "src/compiler/glsl/astc_decoder.glsl"
ASTC_HDR = "meson_generated/src/vulkan/runtime/astc_spv.h"

IMAPPER_MODULE = f'''
// Added by tools/mesa/fixup-android-bp.py (rock5): meson only builds this
// backend when it finds libui, which the android-stub build lacks. Without it
// Mesa uses the fallback gralloc, which reports DRM_FORMAT_MOD_INVALID for
// every buffer.
cc_library_static {{
    name: "{IMAPPER}",
    srcs: ["src/util/u_gralloc/u_gralloc_imapper5_api.cpp"],
    cflags: [
        "-DUSE_IMAPPER4_METADATA_API",
        "-Wno-error",
        "-Wno-unused-parameter",
    ],
    cpp_std: "c++17",
    local_include_dirs: [
        "include",
        "meson_generated/src",
        "src",
        "src/util/u_gralloc",
    ],
    shared_libs: [
        "libcutils",
        "liblog",
        "libnativewindow",
        "libui",
        "libutils",
    ],
    defaults: ["android.hardware.graphics.common-ndk_shared"],
    soc_specific: true,
}}
'''


def die(msg):
    sys.exit(f"!! {msg}")


def insert_after(s, anchor, text, start=0):
    i = s.find(anchor, start)
    if i < 0:
        die(f"Android.bp layout changed, cannot find: {anchor.strip()}")
    i += len(anchor)
    return s[:i] + text + s[i:]


def main():
    if len(sys.argv) != 2:
        die("usage: fixup-android-bp.py <mesa checkout>")
    mesa = sys.argv[1]
    bp_path = os.path.join(mesa, "Android.bp")
    s = open(bp_path).read()
    if IMAPPER in s:
        die("Android.bp is already fixed up (regenerate it first)")

    # 1. ASTC decoder shader: pre-generate, turn the genrule into a copy
    os.makedirs(os.path.join(mesa, os.path.dirname(ASTC_HDR)), exist_ok=True)
    subprocess.run(["glslangValidator", "-V", "-S", "comp", "-x", "-o",
                    os.path.join(mesa, ASTC_HDR), os.path.join(mesa, ASTC_SRC),
                    "--quiet"], check=True)
    m = re.search(r'cmd: "\$\(location\) -V -S comp [^\n]*\n', s)
    if not m:
        die("astc_spv.h genrule not found")
    s = s.replace(m.group(0),
                  f'cmd: "cp $(location {ASTC_HDR}) $(location astc_spv.h); '
                  'cp $(location astc_spv.h) $(location runtime/astc_spv.h); '
                  'cp $(location runtime/astc_spv.h) $(location vulkan/runtime/astc_spv.h)",\n')
    old = f'srcs: ["{ASTC_SRC}"],'
    if s.count(old) != 1:
        die("astc genrule srcs not found exactly once")
    s = s.replace(old, f'srcs: ["{ASTC_HDR}"],')
    old = '    tools: ["glslangValidator"],\n'
    if s.count(old) != 1:
        die("expected exactly one glslangValidator user")
    s = s.replace(old, "")

    # 2. IMapper gralloc backend
    s = insert_after(s, f'    name: "{UGRALLOC}",\n    srcs: ["src/util/u_gralloc/*.c"],\n',
                     '    cflags: ["-DUSE_IMAPPER4_METADATA_API"],\n')
    drv = s.find(f'name: "{DRIVER}"')
    if drv < 0:
        die(f"{DRIVER} not found")
    s = insert_after(s, f'        "{UGRALLOC}",\n', f'        "{IMAPPER}",\n', drv)
    s = insert_after(s, '        "libsync",\n', '        "libui",\n        "libutils",\n', drv)
    s += IMAPPER_MODULE

    open(bp_path, "w").write(s)
    print(f">> fixed up {bp_path} and generated {ASTC_HDR}")


if __name__ == "__main__":
    main()
